import{_ as i,o as t,c as o,a0 as n}from"./chunks/framework.DB31oXgM.js";const m=JSON.parse('{"title":"ADR 005: Fixed-Point Numeric Type for Cross-Platform Determinism","description":"","frontmatter":{},"headers":[],"relativePath":"adr/005-fixed-point-numeric-type.md","filePath":"adr/005-fixed-point-numeric-type.md"}'),a={name:"adr/005-fixed-point-numeric-type.md"};function r(s,e,c,d,l,p){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-005-fixed-point-numeric-type-for-cross-platform-determinism" tabindex="-1">ADR 005: Fixed-Point Numeric Type for Cross-Platform Determinism <a class="header-anchor" href="#adr-005-fixed-point-numeric-type-for-cross-platform-determinism" aria-label="Permalink to &quot;ADR 005: Fixed-Point Numeric Type for Cross-Platform Determinism&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Floating point operations (<code>f32</code>, <code>f64</code>) across different CPU architectures (x86_64 vs ARM64/Apple Silicon) and compiler optimization levels yield subtle non-deterministic divergence due to FMA (Fused Multiply-Add) instructions, extended precision registers, and rounding mode differences. A single sub-epsilon difference causes desynchronization in lockstep/rollback simulations.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We implement a dedicated <code>FixedI32</code> Q16.16 signed fixed-point type (16 bits integer, 16 bits fractional):</p><ul><li>Zero floating-point instructions in simulation, state, and physics.</li><li>Integer arithmetic (<code>wrapping_add</code>, <code>wrapping_sub</code>, 64-bit intermediate multiplication and division).</li><li>Integer square root (<code>isqrt</code>) and deterministic trigonometric sine/cosine lookup tables (256-entry quadrant LUT).</li><li>Explicit <code>serde::Serialize</code> and <code>serde::Deserialize</code> implementations storing exact 32-bit raw integer payloads.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Guaranteed bit-identical simulation results across Apple Silicon, x86_64 Linux servers, and WASM/browser clients.</li><li>Arithmetic operations execute in 1–2 clock cycles.</li><li>Dynamic range is bounded to [-32,768.0, +32,767.99998] with precision of ~0.000015 (1/65536), which is ideal for 2D arena game kinematics.</li></ul>',10)])])}const f=i(a,[["render",r]]);export{m as __pageData,f as default};
